### `scheduled` supersession migrates BOTH contextMap and pendingSrsMap (Finding: supersession)

When a failed/skipped analysis is retried, the coordinator emits a `scheduled` outcome carrying `previousRequestId` (the old request id) and a new `requestId`. The decision state keyed by the OLD id must be re-keyed to the NEW id, or the retried analysis resolves with `ctx = null` and silently loses blunder-recording eligibility.

```typescript
// Returns 'accepted' when the slot may be (re)opened, 'ignored' when the previous
// request is tombstoned and the caller must suppress the new request entirely (Finding 1).
private migrateOnReschedule(outcome: AnalysisOutcome): 'accepted' | 'ignored' {
  const prev = outcome.previousRequestId;
  if (!prev) return 'accepted';                       // fresh schedule, nothing to migrate
  if (this.abandonedRequests.has(prev)) return 'ignored';   // tombstoned: do not resurrect

  // 1. Blunder context migration (old → new); delete old entry
  const ctx = this.contextMap.get(prev);
  if (ctx !== undefined) {
    this.contextMap.set(outcome.requestId, ctx);
    this.contextMap.delete(prev);
  }

  // 2. SRS pendingSrsMap migration (preserves registrationSeq for FIFO order)
  const srs = this.pendingSrsMap.get(prev);
  if (srs !== undefined) {
    this.pendingSrsMap.set(outcome.requestId, srs);   // keep same registrationSeq
    this.pendingSrsMap.delete(prev);
    // Find the slot by its STABLE srsDecisionId, then UPDATE its current requestId
    // to the new id so a later analysis-retry timeout tombstones the right id (Finding 1).
    const slot = this.findSrsSlotBySrsDecisionId(srs.srsDecisionId);
    if (slot) {
      slot.requestId = outcome.requestId;             // re-point identity to the live request
      if (slot.status === 'awaiting_retry') {
        cancelTimer(slot.analysisRetryTimeoutId);
        slot.status = 'awaiting_analysis';
      }
    }
  }

  // 3. Migrate the frontier slot: failed_provisional → pending_analysis under new id
  //    (cancel the 30s abandonment timer so the retry isn't abandoned mid-flight)
  const fslot = this.frontier.get(outcome.moveIndex);
  if (fslot && (fslot.status === 'failed_provisional' || fslot.status === 'skipped_provisional')) {
    cancelTimer(fslot.retryTimeoutId);
    // The case 'scheduled' handler overwrites this slot to pending_analysis with the
    // new requestId; we only need to clear the stale timer here.
  }

  // 4. Clear terminatedRequests for prev (retry is now live)
  this.terminatedRequests.delete(prev);

  // 5. Dedup: do NOT carry processedOutcomes for prev — the new requestId is distinct
  return 'accepted';
}
```

`processedOutcomes` keys by the resolved request id, so the new id is naturally un-deduped; the old id's dedup entry is irrelevant after migration.

