### Outbox entry union

```typescript
type SrsOutboxStatus =
  | 'awaiting_analysis' | 'awaiting_retry' | 'pending'
  | 'awaiting_http_retry' | 'in_flight' | 'succeeded' | 'terminal_error';
type BlunderOutboxStatus =
  | 'pending' | 'awaiting_http_retry' | 'in_flight' | 'succeeded' | 'terminal_error';

interface SrsOutboxEntry {
  kind: 'srs';
  blunderId: number;
  srsDecisionId: string;     // STABLE identity — minted once at registration, survives reschedule.
                             //   Lookups (findSrsSlotBy*) key on this, never on requestId.
  requestId: string;         // CURRENT request id — updated on every reschedule (Finding 1).
                             //   Used to tombstone the right id on analysis-retry timeout.
  registrationSeq: number; moveIndex: number;
  payload: SrsReviewRequest | null; status: SrsOutboxStatus; terminalError?: string;
  analysisRetryTimeoutId?: ReturnType<typeof setTimeout>;
  httpRetryTimeoutId?: ReturnType<typeof setTimeout>;
  attempts: number;
}
// Lookup helper: key by the stable srsDecisionId, NOT requestId.
// findSrsSlotBySrsDecisionId(id) replaces the earlier findSrsSlotByRequestId.
// Where a requestId is on hand, resolve it to srsDecisionId via pendingSrsMap first.
interface BlunderOutboxEntry {
  kind: 'blunder'; moveIndex: number; payload: RecordBlunderRequest;
  status: BlunderOutboxStatus; terminalError?: string;
  httpRetryTimeoutId?: ReturnType<typeof setTimeout>; attempts: number;
}
```

